const std=@import("std");
fn putd(o:[*]u8,p:usize,x:f64)void{const bits=@as(u64,@bitCast(x));for(0..8)|k|o[p+k]=@truncate(bits>>(8*k));}
export fn ordinary_least_squares_regressor(v:[*]const i64,n:usize,o:[*]u8,cap:usize)i64{if(n<6)return -1;const nr=v[0];const f=v[1];const t=v[2];if(nr<2 or nr>8 or f!=2 or t<1 or t>3 or n!=@as(usize,@intCast(3+nr*3+t*2)))return -1;var g=[_] [3]f64{.{0,0,0},.{0,0,0},.{0,0,0}};var b=[_]f64{0,0,0};var p:usize=3;for(0..@intCast(nr)) |_|{const x=v[p];const y=v[p+1];const z=v[p+2];p+=3;if(x < -100 or x>100 or y < -100 or y>100 or z < -1000 or z>1000)return -1;const row=[_]f64{@floatFromInt(x),@floatFromInt(y),1};for(0..3)|i|{b[i]+=row[i]*@as(f64,@floatFromInt(z));for(0..3)|j|g[i][j]+=row[i]*row[j];}}for(0..3)|c|{var q=c;for(c+1..3)|r|{if(@abs(g[r][c])>@abs(g[q][c]))q=r;}if(@abs(g[q][c])<1e-12)return -1;for(0..3)|j|{const z=g[c][j];g[c][j]=g[q][j];g[q][j]=z;}const z=b[c];b[c]=b[q];b[q]=z;const s=g[c][c];for(c..3)|j|g[c][j]/=s;b[c]/=s;for(0..3)|r|{if(r!=c){const k=g[r][c];for(c..3)|j|g[r][j]-=k*g[c][j];b[r]-=k*b[c];}}}if(cap<@as(usize,@intCast(t))*8)return -2;for(0..@intCast(t))|r|{const x=v[p];const y=v[p+1];p+=2;if(x < -100 or x>100 or y < -100 or y>100)return -1;putd(o,r*8,@as(f64,@floatFromInt(x))*b[0]+@as(f64,@floatFromInt(y))*b[1]+b[2]);}return t*8;}
